import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Br18A9IS.js";import{c as i,l as a,s as o}from"./chunks/assets.U8FFjQeS.js";var s=JSON.parse(`{"title":"Overview","description":"Understand how WarpDrive uses signals as side-signals or gates to notify consumers of cache changes while letting you plug in your own or your framework's signals implementation.","frontmatter":{"title":"Overview","description":"Understand how WarpDrive uses signals as side-signals or gates to notify consumers of cache changes while letting you plug in your own or your framework's signals implementation."},"headers":[],"relativePath":"guides/the-manual/reactivity/index.md","filePath":"guides/the-manual/reactivity/index.md"}`),c={name:`guides/the-manual/reactivity/index.md`};function l(n,s,c,l,u,d){return r(),t(`div`,null,[...s[0]||=[e(`<h1 id="reactivity" tabindex="-1">Reactivity <a class="header-anchor" href="#reactivity" aria-label="Permalink to “Reactivity”">​</a></h1><img src="`+a+`" style="height:150px;float:right;margin:1em;padding:2em 0 2em 4em;border-left:.05em solid #999999;" title="" alt=""><p><strong><em>Warp</em>Drive</strong> relies on <a href="https://github.com/tc39/proposal-signals#readme" target="_blank" rel="noreferrer">signals</a> to enable universal fine-grained reactivity, but where most projects choose a specific signals implementation for consumers to use, <strong><em>Warp</em>Drive</strong> allows you to <strong>bring your own or use your framework&#39;s</strong>.</p><p>The concept is simple: instead of relying on specifics of signal implementations that may differ, <strong>we use signals purely as just that - a signal</strong>. The signal itself is never responsible for managing state, storage, or value comparisons.</p><p>Lightweight hooks translate the basic <em>create/consume/notify</em> signal operations into implementation specifics for one (or more) signal libraries.</p><p>This enables us to be compatible with even the most lightweight and performant signals implementations. The simplicity of this approach keeps <strong><em>Warp</em>Drive</strong> relatively future-proof should the spec significantly change or fail to advance. Of course, we hope it becomes a first-class feature of both the language and web APIs!</p><p>Signals are used to alert the reactive consumers to changes in the underlying cache. E.g. a signal is associated to a value, but does not serve as the cache for that value directly. We refer to this as a &quot;gate&quot;, though the pattern has also been referred to as &quot;side-signals&quot;.</p><figure><img class="dark-only" src="`+i+`" alt="management of signals in WarpDrive" width="100%"><img class="light-only" src="`+o+`" alt="management of signals in WarpDrive" width="100%"><figcaption>WarpDrive uses Side Signals</figcaption></figure><p>We find this approach naturally solves many of the concerns and limitations given around various signals implementations, and fits <strong><em>Warp</em>Drive</strong>&#39;s specific use cases exceedingly well. <strong><em>Warp</em>Drive</strong> manages normalized caches of raw data - usually json - that are typically asynchronously retrieved from latent sources. By separating signal from storage, we can safely perform cache updates even when multiple asynchronous steps are involved to do so, while only notifying consumers when updates are complete.</p>`,9)]])}var u=n(c,[[`render`,l]]);export{s as __pageData,u as default};